// 素材：SFXMint feedback-confirm-41 · Gentle Marimba (CC0 1.0)
//
// 素材是**三段式**的（马林巴），五段按素材原结构组合，不做移调：
//
//   素材段 A     0~140 ms  短音 350Hz
//   素材段 B   145~450 ms  主音 590Hz
//   素材段 C   455~712 ms  收尾 440Hz
//
//   段            构成                    时长
//   DONE          A+B+C（完整三段）      702ms
//   ATTENTION     B + 间隙 + B          700ms
//   CONNECTED     B（单块，短）          260ms
//   SESSION_END   A + C                  397ms
//   KEY           A（极短切片）          110ms
//
// 为什么保留素材原结构、而不是移调造语义：
//   素材自带「低→高→落」走向，DONE 要的却是「高→低」下行 ——
//   下行在听觉上天然是「结束」，那是 DONE 的语义，而上行是「开始」。
//   移调只能改音高、改不了走向，强行套用会让「完成」听着像「开始」。
//   所以这里按「取哪几块 + 重复几次」区分语义，音色零损失。
//
// 采样率 24000Hz 与 I2S 输出一致，运行时零重采样。
// 单声道 int16，播放时复制到左右声道（I2S 配的是立体声，
// 直接送单声道会让 L/R 错位，听起来是失真加噪声）。
//
// 响度：五段先按发声区 RMS 拉齐（相对响度），再乘同一个
// 全局增益把最响段顶到 92%（绝对响度）。按键音再单独 -6dB ——
// 它是唯一会被用户连按的声音，做响会迅速变成噪音。
